import express from 'express';
import path from 'path';
import fs from 'fs/promises';
import { fileURLToPath } from 'url';
import { randomUUID } from 'crypto';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_PATH = path.join(__dirname, 'data', 'books.json');

const app = express();
app.set('view engine', 'ejs');
app.use(express.urlencoded({ extended: true }));
app.use(express.static(path.join(__dirname, 'public')));

async function readBooks() {
  try {
    const raw = await fs.readFile(DATA_PATH, 'utf8');
    return JSON.parse(raw || '[]');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function writeBooks(books) {
  await fs.mkdir(path.dirname(DATA_PATH), { recursive: true });
  await fs.writeFile(DATA_PATH, JSON.stringify(books, null, 2));
}

app.get('/', async (req, res) => {
  const books = await readBooks();
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  res.render('index', { reading, finished });
});

app.post('/books', async (req, res) => {
  const { title, author, notes } = req.body;
  const books = await readBooks();
  books.push({
    id: randomUUID(),
    title: title?.trim() || 'Untitled',
    author: author?.trim() || '',
    notes: notes?.trim() || '',
    finished: false,
    createdAt: new Date().toISOString(),
  });
  await writeBooks(books);
  res.redirect('/');
});

app.post('/books/:id/finish', async (req, res) => {
  const books = await readBooks();
  const book = books.find((b) => b.id === req.params.id);
  if (book) {
    book.finished = true;
    book.finishedAt = new Date().toISOString();
    await writeBooks(books);
  }
  res.redirect('/');
});

app.get('/books/:id', async (req, res) => {
  const books = await readBooks();
  const book = books.find((b) => b.id === req.params.id);
  if (!book) return res.status(404).send('Book not found');
  res.render('book', { book });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});

